import { existsSync, readdirSync, readFileSync } from "node:fs";
import { URL } from "node:url";
import eslint from "@eslint/js";
import { builtinRules } from "eslint/use-at-your-own-risk";
import prettierRecommended from "eslint-plugin-prettier/recommended";
import simpleImportSort from "eslint-plugin-simple-import-sort";
import unusedImports from "eslint-plugin-unused-imports";
import tseslint from "typescript-eslint";

export const SHARED_MAX_LEN_OPTIONS = {
  code: 100,
  tabWidth: 2,
  ignoreUrls: true,
  ignoreStrings: true,
  ignoreTemplateLiterals: true,
  ignoreRegExpLiterals: true
};

export const SHARED_RESTRICTED_SYNTAX_LIST = [
  {
    selector:
      ":matches(ImportDeclaration, ExportNamedDeclaration, ExportAllDeclaration, ImportExpression)[source.value=/^[.#~].*\\.js$/]",
    message: "Import the .ts file itself, not NodeNext's .js output name."
  },
  {
    selector:
      ":matches(MethodDefinition[kind!='constructor'], PropertyDefinition, TSParameterProperty)[accessibility='private']",
    message:
      "Use an ES private member (#name), not the TypeScript private keyword; only a constructor stays private."
  },
  {
    selector:
      ":matches(MethodDefinition[kind='method'][value.params.length>0][value.returnType.typeAnnotation.type='TSBooleanKeyword'], TSMethodSignature[params.length>0][returnType.typeAnnotation.type='TSBooleanKeyword'])[key.name!=/^getIs[A-Z]/]",
    message: "A boolean query with parameters is named getIs…(…)."
  },
  {
    selector:
      ":matches(MethodDefinition[kind='method'][value.params.length=0]:matches([key.name=/^get[A-Z]/], [value.returnType.typeAnnotation.type='TSBooleanKeyword']), TSMethodSignature[params.length=0]:matches([key.name=/^get[A-Z]/], [returnType.typeAnnotation.type='TSBooleanKeyword']))",
    message:
      "A query without parameters is an accessor: get x() or get isX(); an interface declares it readonly x."
  },
  {
    selector:
      "MethodDefinition[kind='get'][value.returnType.typeAnnotation.type='TSBooleanKeyword'][key.name!=/^is[A-Z]/]",
    message: "A boolean accessor is named is…"
  },
  {
    selector:
      ":matches(MethodDefinition[value.returnType.typeAnnotation.type='TSVoidKeyword'], TSMethodSignature[returnType.typeAnnotation.type='TSVoidKeyword'])[key.name=/^get[A-Z]/]",
    message: "A get… method is a query and returns a value; a command keeps its verb."
  },
  {
    selector: "ExportDefaultDeclaration > ObjectExpression > SpreadElement",
    message: "A module default-exports its own values, never a spread."
  },
  {
    selector:
      ":matches(ForStatement, ForInStatement, ForOfStatement, WhileStatement, DoWhileStatement)[body.type!='BlockStatement']",
    message: "A loop body goes in braces."
  },
  {
    selector:
      "IfStatement[consequent.type!='BlockStatement']:matches([consequent.type!=/^(ReturnStatement|ContinueStatement)$/], [alternate.type])",
    message:
      "Only a one-line `if (…) return …;` or `if (…) continue;` goes without braces; any other body, and any if with an else, takes braces."
  },
  {
    selector:
      "IfStatement[alternate.type][alternate.type!='BlockStatement'][alternate.type!='IfStatement']",
    message: "An else body goes in braces."
  }
];

export const SHARED_RULES_MAP = {
  "prettier/prettier": "error",
  "simple-import-sort/imports": "error",
  "no-duplicate-imports": "error",
  curly: ["error", "multi-line"],
  eqeqeq: ["error", "always"],
  "@typescript-eslint/consistent-type-imports": [
    "error",
    {
      prefer: "type-imports",
      fixStyle: "inline-type-imports"
    }
  ],
  "@typescript-eslint/no-explicit-any": "warn",
  "@typescript-eslint/ban-ts-comment": "off",
  "@typescript-eslint/no-empty-function": "off",
  "@typescript-eslint/no-namespace": "off",
  "@typescript-eslint/no-non-null-assertion": "off",
  "@typescript-eslint/no-unused-vars": "off",
  "unused-imports/no-unused-imports": "error",
  "unused-imports/no-unused-vars": [
    "warn",
    {
      argsIgnorePattern: "^_"
    }
  ],
  "max-len": ["error", SHARED_MAX_LEN_OPTIONS],
  "no-restricted-syntax": ["error", ...SHARED_RESTRICTED_SYNTAX_LIST]
};

export const SHARED_TYPE_AWARE_RULES_MAP = {
  "@typescript-eslint/prefer-nullish-coalescing": "error",
  "@typescript-eslint/prefer-optional-chain": "error",
  "@typescript-eslint/no-unnecessary-type-parameters": "error"
};

const TS_RULE_PREFIX = "@typescript-eslint/";

export const buildSharedConfigList = ({
  ignoresList = [],
  tsFilesList = ["**/*.ts", "**/*.tsx"]
} = {}) =>
  tseslint.config(
    { ignores: [...ignoresList] },
    eslint.configs.recommended,
    tseslint.configs.recommended,
    prettierRecommended,
    {
      files: [...tsFilesList],
      languageOptions: { parserOptions: { projectService: true } },
      plugins: { "simple-import-sort": simpleImportSort, "unused-imports": unusedImports },
      rules: { ...SHARED_RULES_MAP, ...SHARED_TYPE_AWARE_RULES_MAP }
    }
  );

/** One ESLint glob per line, in order; blank lines and # comments skipped. */
export const readIgnoreFile = fileUrl =>
  readFileSync(fileUrl, "utf8")
    .split("\n")
    .map(line => line.trim())
    .filter(line => line !== "" && !line.startsWith("#"));

/** The folders under `dirUrl` that hold a package.json, sorted. */
export const listPackageFolders = dirUrl =>
  readdirSync(dirUrl, { withFileTypes: true })
    .filter(
      entry => entry.isDirectory() && existsSync(new URL(`${entry.name}/package.json`, dirUrl))
    )
    .map(entry => entry.name)
    .sort();

const findRule = ruleName => {
  const rule = ruleName.startsWith(TS_RULE_PREFIX)
    ? tseslint.plugin.rules?.[ruleName.slice(TS_RULE_PREFIX.length)]
    : builtinRules.get(ruleName);
  if (rule === undefined) {
    throw new Error(`No rule ${ruleName} to copy.`);
  }
  return rule;
};

/**
 * A plugin of existing rules under new names, one per concern. A later block that sets a rule
 * replaces its whole option list, so a concern on its own copy never restates another's options.
 */
export const buildRuleCopiesPlugin = copiesMap => ({
  rules: Object.fromEntries(
    Object.entries(copiesMap).map(([copyName, ruleName]) => [copyName, findRule(ruleName)])
  )
});

